-- TEST ONLY gcgjpfidppaioambcatq. No existing review or share setting is initialized.
create table if not exists rpg_private.reading_share_settings(teacher_id uuid primary key,class_sharing boolean not null default false);
alter table rpg_private.reading_share_settings alter column class_sharing set default false;
alter table rpg_private.reading_share_settings enable row level security;
revoke all on rpg_private.reading_share_settings from public,anon,authenticated;
create or replace function public.teacher_reading_share_policy()
returns jsonb language plpgsql security definer stable set search_path='' as $$
begin if auth.uid() is null then raise exception '선생님 로그인이 필요해요.';end if;return jsonb_build_object('class_sharing',coalesce((select class_sharing from rpg_private.reading_share_settings where teacher_id=auth.uid()),false));end; $$;
create or replace function public.teacher_set_reading_share_policy(p_enabled boolean)
returns jsonb language plpgsql security definer set search_path='' as $$
begin if auth.uid() is null or p_enabled is null then raise exception '선생님 로그인을 확인해 주세요.';end if;insert into rpg_private.reading_share_settings(teacher_id,class_sharing)values(auth.uid(),p_enabled)on conflict(teacher_id)do update set class_sharing=excluded.class_sharing;return jsonb_build_object('ok',true,'class_sharing',p_enabled);end; $$;
revoke all on function public.teacher_reading_share_policy() from public,anon;
revoke all on function public.teacher_set_reading_share_policy(boolean) from public,anon;
grant execute on function public.teacher_reading_share_policy() to authenticated;
grant execute on function public.teacher_set_reading_share_policy(boolean) to authenticated;
create or replace function public.student_reading_rules(p_token text)
returns jsonb language plpgsql security definer stable set search_path='' as $$
declare sid bigint; tid uuid;
begin sid:=public.student_for_token(p_token);if sid is null then raise exception '다시 로그인해 주세요.';end if;select teacher_id into tid from public.students where id=sid;return jsonb_build_object('today',timezone('Asia/Seoul',now())::date,'weekly_count',(select count(*)from public.reading_reviews where student_id=sid and created_at>=date_trunc('week',now())),'class_sharing',coalesce((select class_sharing from rpg_private.reading_share_settings where teacher_id=tid),false));end; $$;
revoke all on function public.student_reading_rules(text) from public;
grant execute on function public.student_reading_rules(text) to anon,authenticated;
create or replace function rpg_private.guard_reading_date()
returns trigger language plpgsql set search_path='' as $$
begin if new.read_date>timezone('Asia/Seoul',now())::date then raise exception '읽은 날은 한국시간 오늘까지 고를 수 있어요.';end if;return new;end; $$;
revoke all on function rpg_private.guard_reading_date() from public,anon,authenticated;
drop trigger if exists guard_reading_date on public.reading_reviews;
create trigger guard_reading_date before insert or update of read_date on public.reading_reviews for each row execute function rpg_private.guard_reading_date();
create table if not exists rpg_private.reading_revisions(id bigint generated by default as identity primary key,review_id bigint not null references public.reading_reviews(id)on delete cascade,student_id bigint not null references public.students(id)on delete cascade,before_text jsonb not null,after_text jsonb not null,changed_at timestamptz not null default now());
alter table rpg_private.reading_revisions enable row level security;
revoke all on rpg_private.reading_revisions from public,anon,authenticated;
create index if not exists reading_revisions_owner on rpg_private.reading_revisions(student_id,review_id,id desc);
create or replace function rpg_private.record_reading_revision()
returns trigger language plpgsql security definer set search_path='' as $$
begin if row(old.book_title,old.read_date,old.summary,old.thoughts,old.recommendation_rating,old.recommendation_reason,old.retry_count)is distinct from row(new.book_title,new.read_date,new.summary,new.thoughts,new.recommendation_rating,new.recommendation_reason,new.retry_count)then
insert into rpg_private.reading_revisions(review_id,student_id,before_text,after_text)values(old.id,old.student_id,jsonb_build_object('book_title',old.book_title,'summary',old.summary,'thoughts',old.thoughts,'recommendation_rating',old.recommendation_rating,'recommendation_reason',old.recommendation_reason,'rejection_reason',old.rejection_reason),jsonb_build_object('book_title',new.book_title,'summary',new.summary,'thoughts',new.thoughts,'recommendation_rating',new.recommendation_rating,'recommendation_reason',new.recommendation_reason));end if;return new;end; $$;
revoke all on function rpg_private.record_reading_revision() from public,anon,authenticated;
drop trigger if exists record_reading_revision on public.reading_reviews;
create trigger record_reading_revision after update on public.reading_reviews for each row execute function rpg_private.record_reading_revision();
create or replace function public.student_reading_revisions(p_token text,p_review_id bigint)
returns jsonb language plpgsql security definer stable set search_path='' as $$
declare sid bigint; result jsonb;
begin sid:=public.student_for_token(p_token);if sid is null then raise exception '다시 로그인해 주세요.';end if;select coalesce(jsonb_agg(to_jsonb(x)order by x.id desc),'[]'::jsonb)into result from(select v.id,v.before_text,v.after_text,v.changed_at from rpg_private.reading_revisions v join public.reading_reviews r on r.id=v.review_id where r.id=p_review_id and r.student_id=sid and v.student_id=sid order by v.id desc limit 10)x;return jsonb_build_object('versions',result);end; $$;
create or replace function public.teacher_reading_revisions(p_review_id bigint)
returns jsonb language plpgsql security definer stable set search_path='' as $$
declare result jsonb;
begin if auth.uid() is null then raise exception '선생님 로그인이 필요해요.';end if;select coalesce(jsonb_agg(to_jsonb(x)order by x.id desc),'[]'::jsonb)into result from(select v.id,v.before_text,v.after_text,v.changed_at from rpg_private.reading_revisions v join public.reading_reviews r on r.id=v.review_id join public.students s on s.id=r.student_id where r.id=p_review_id and s.teacher_id=auth.uid() and v.student_id=r.student_id order by v.id desc limit 10)x;return jsonb_build_object('versions',result);end; $$;
revoke all on function public.student_reading_revisions(text,bigint) from public;
revoke all on function public.teacher_reading_revisions(bigint) from public,anon;
grant execute on function public.student_reading_revisions(text,bigint) to anon,authenticated;
grant execute on function public.teacher_reading_revisions(bigint) to authenticated;
create or replace function public.student_reading_shelf_search(p_token text,p_scope text default 'mine',p_author text default '',p_before_id bigint default null)
returns jsonb language plpgsql security definer stable set search_path='' as $$
declare sid bigint;tid uuid;result jsonb;shared boolean;
begin sid:=public.student_for_token(p_token);if sid is null then raise exception '다시 로그인해 주세요.';end if;if p_scope not in('mine','class')or length(coalesce(p_author,''))>40 then raise exception '책장을 다시 확인해 주세요.';end if;select teacher_id into tid from public.students where id=sid;shared:=coalesce((select class_sharing from rpg_private.reading_share_settings where teacher_id=tid),false);
with candidates as(select r.id as review_id,r.book_title,r.read_date,r.summary,r.thoughts,r.recommendation_rating,r.recommendation_reason,r.status,coalesce(s.nickname,'우리 반 친구')as author_nickname,(r.student_id=sid)as mine from public.reading_reviews r join public.students s on s.id=r.student_id where (p_before_id is null or r.id<p_before_id) and ((p_scope='mine'and r.student_id=sid)or(p_scope='class'and shared and tid is not null and s.teacher_id=tid and r.status='approved')) and position(lower(coalesce(p_author,''))in lower(coalesce(s.nickname,'우리 반 친구')))>0 order by r.id desc limit 21),page as(select *from candidates order by review_id desc limit 20)
select jsonb_build_object('reviews',coalesce((select jsonb_agg(to_jsonb(p)order by review_id desc)from page p),'[]'::jsonb),'has_more',(select count(*)>20 from candidates),'next_before_id',(select min(review_id)from page),'class_sharing',shared)into result;return result;end; $$;
revoke all on function public.student_reading_shelf_search(text,text,text,bigint) from public;
grant execute on function public.student_reading_shelf_search(text,text,text,bigint) to anon,authenticated;
create or replace function public.student_reading_bookmarks(p_token text,p_ids bigint[])
returns jsonb language plpgsql security definer stable set search_path='' as $$
declare sid bigint;tid uuid;shared boolean;rows jsonb;
begin sid:=public.student_for_token(p_token);if sid is null then raise exception '다시 로그인해 주세요.';end if;if cardinality(p_ids)>30 then raise exception '책갈피는 30개까지 보관해요.';end if;select teacher_id into tid from public.students where id=sid;shared:=coalesce((select class_sharing from rpg_private.reading_share_settings where teacher_id=tid),false);select coalesce(jsonb_agg(to_jsonb(x)order by x.review_id desc),'[]'::jsonb)into rows from(select r.id as review_id,r.book_title,r.read_date,r.summary,r.thoughts,r.recommendation_rating,r.recommendation_reason,r.status,coalesce(s.nickname,'우리 반 친구')as author_nickname,(r.student_id=sid)as mine from public.reading_reviews r join public.students s on s.id=r.student_id where r.id=any(p_ids)and(r.student_id=sid or(shared and s.teacher_id=tid and r.status='approved')))x;return jsonb_build_object('reviews',rows,'has_more',false,'class_sharing',shared);end; $$;
revoke all on function public.student_reading_bookmarks(text,bigint[]) from public;
grant execute on function public.student_reading_bookmarks(text,bigint[]) to anon,authenticated;

create or replace function public.student_reading_shelf(p_token text,p_scope text default 'mine',p_before_id bigint default null)
returns jsonb language sql security definer stable set search_path='' as $$ select public.student_reading_shelf_search(p_token,p_scope,'',p_before_id); $$;
revoke all on function public.student_reading_shelf(text,text,bigint) from public;
grant execute on function public.student_reading_shelf(text,text,bigint) to anon,authenticated;
